@import "@fontsource-variable/inter";
@import "@fontsource-variable/geist-mono";

/* Dark (faithful): page #07080a, panels #111214, hairlines white at 6–10 %, text white with
   #9c9c9d / #6a6b6c for secondary copy, the white keycap button as primary, coral red
   (#ff6363) as the single accent and deep crimson as the glow. Light is the same on white. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.17 0.006 255);
  --card: oklch(0.985 0.002 255);
  --card-foreground: oklch(0.17 0.006 255);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.17 0.006 255);
  --primary: oklch(0.2 0.006 255);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.965 0.003 255);
  --secondary-foreground: oklch(0.2 0.006 255);
  --muted: oklch(0.955 0.003 255);
  --muted-foreground: oklch(0.5 0.008 255);
  --accent: oklch(0.94 0.004 255);
  --accent-foreground: oklch(0.2 0.006 255);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.17 0.006 255 / 10%);
  --input: oklch(0.17 0.006 255 / 14%);
  --ring: oklch(0.17 0.006 255 / 35%);
  --highlight: oklch(0.62 0.21 24);
  --highlight-foreground: oklch(0.985 0 0);
  --glow: oklch(0.6 0.22 25);
  --chart-1: oklch(0.7 0.19 22);
  --chart-2: oklch(0.72 0.15 160);
  --chart-3: oklch(0.72 0.12 235);
  --chart-4: oklch(0.82 0.16 85);
  --chart-5: oklch(0.6 0.2 275);
  --sidebar: oklch(0.985 0.002 255);
  --sidebar-foreground: oklch(0.17 0.006 255);
  --sidebar-primary: oklch(0.2 0.006 255);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.94 0.004 255);
  --sidebar-accent-foreground: oklch(0.2 0.006 255);
  --sidebar-border: oklch(0.17 0.006 255 / 10%);
  --sidebar-ring: oklch(0.17 0.006 255 / 35%);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --typeface-display: var(--typeface-body);
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 75.25rem;
  --page-gutter: 1.5rem;
  --section-y: 10.5rem;
}

.dark {
  --background: oklch(0.135 0.005 255);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.185 0.005 255);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.21 0.005 255);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.92 0 0);
  --primary-foreground: oklch(0.23 0.005 255);
  --secondary: oklch(0.23 0.005 255);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.2 0.005 255);
  --muted-foreground: oklch(0.7 0.003 255);
  --accent: oklch(0.25 0.005 255);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.7 0.19 22);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(1 0 0 / 8%);
  --input: oklch(1 0 0 / 12%);
  --ring: oklch(1 0 0 / 30%);
  --highlight: oklch(0.7 0.19 22);
  --highlight-foreground: oklch(0.135 0.005 255);
  --glow: oklch(0.5 0.21 25);
  --chart-1: oklch(0.7 0.19 22);
  --chart-2: oklch(0.77 0.15 160);
  --chart-3: oklch(0.78 0.12 235);
  --chart-4: oklch(0.85 0.16 85);
  --chart-5: oklch(0.6 0.2 275);
  --sidebar: oklch(0.185 0.005 255);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.7 0.19 22);
  --sidebar-primary-foreground: oklch(0.135 0.005 255);
  --sidebar-accent: oklch(0.25 0.005 255);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 8%);
  --sidebar-ring: oklch(1 0 0 / 30%);
}
